const body = $json;

function normalizar(texto) {
  return texto
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function obtenerCampo(posiblesNombres) {
  const keys = Object.keys(body);

  for (const posible of posiblesNombres) {
    const posibleNormalizado = normalizar(posible);

    for (const key of keys) {
      const keyNormalizado = normalizar(key);

      if (keyNormalizado === posibleNormalizado) {
        return body[key];
      }
    }
  }

  return "";
}

const nombre = obtenerCampo(["Nombre completo", "nombre"]);
const correo = obtenerCampo(["Correo electronico", "Correo electrónico", "correo"]);
const departamento = obtenerCampo(["Departamento", "departamento"]) || "No especificado";
const categoria = obtenerCampo(["Categoría del problema", "Categoria del problema", "categoria"]);
const urgencia = obtenerCampo(["Nivel de urgencia", "urgencia"]);
const descripcion = obtenerCampo(["Descripción del problema", "Descripcion del problema", "descripcion"]);

const fecha = new Date();
const timestamp = fecha.getTime();

let prioridad = "Media";

const urgenciaLower = normalizar(urgencia || "");
const categoriaLower = normalizar(categoria || "");
const descripcionLower = normalizar(descripcion || "");

if (
  urgenciaLower.includes("critica") ||
  descripcionLower.includes("no funciona") ||
  descripcionLower.includes("caido") ||
  descripcionLower.includes("urgente")
) {
  prioridad = "Crítica";
} else if (
  urgenciaLower.includes("alta") ||
  categoriaLower.includes("internet") ||
  categoriaLower.includes("sistema")
) {
  prioridad = "Alta";
} else if (urgenciaLower.includes("baja")) {
  prioridad = "Baja";
}

let tecnico = "María González";

if (categoriaLower.includes("internet") || categoriaLower.includes("red")) {
  tecnico = "Carlos Méndez";
} else if (categoriaLower.includes("computadora") || categoriaLower.includes("hardware")) {
  tecnico = "Ana López";
} else if (categoriaLower.includes("sistema") || categoriaLower.includes("software")) {
  tecnico = "Luis Ramírez";
} else if (categoriaLower.includes("impresora")) {
  tecnico = "María González";
}

return {
  json: {
    codigo_ticket: `HD-${timestamp}`,
    nombre,
    correo,
    departamento,
    categoria,
    descripcion,
    urgencia,
    prioridad,
    estado: "Nuevo",
    tecnico_asignado: tecnico,
    mensaje: "Ticket preparado correctamente"
  }
};

const data = $json.reporte;
const resumen = data.resumen;
const tickets = data.ultimos_tickets || [];

const fecha = new Date().toLocaleString("es-GT", {
  timeZone: "America/Guatemala"
});

const filasTickets = tickets.map(t => `
  <tr>
    <td>${t.codigo_ticket}</td>
    <td>${t.nombre}</td>
    <td>${t.departamento || "No especificado"}</td>
    <td>${t.categoria}</td>
    <td>${t.urgencia}</td>
    <td>${t.prioridad}</td>
    <td>${t.estado}</td>
    <td>${t.tecnico_asignado || "Sin asignar"}</td>
    <td>${new Date(t.fecha_creacion).toLocaleString("es-GT", { timeZone: "America/Guatemala" })}</td>
  </tr>
`).join("");

const html = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Reporte HelpDesk</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      margin: 30px;
      color: #222;
    }
    h1 {
      background: #1f4e79;
      color: white;
      padding: 15px;
      border-radius: 8px;
    }
    .fecha {
      color: #555;
      margin-bottom: 20px;
    }
    .cards {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-bottom: 25px;
    }
    .card {
      border: 1px solid #ddd;
      border-radius: 8px;
      padding: 15px;
      background: #f8f8f8;
      text-align: center;
    }
    .card h2 {
      margin: 0;
      font-size: 28px;
      color: #1f4e79;
    }
    .card p {
      margin: 5px 0 0 0;
      font-weight: bold;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
      margin-bottom: 20px;
    }
    th {
      background: #1f4e79;
      color: white;
      padding: 8px;
    }
    td {
      border: 1px solid #ccc;
      padding: 8px;
    }
    tr:nth-child(even) {
      background: #f2f2f2;
    }
    .footer {
      margin-top: 30px;
      font-size: 12px;
      color: #666;
      border-top: 1px solid #ccc;
      padding-top: 10px;
    }
  </style>
</head>
<body>

  <h1>Reporte Automático de Tickets - HelpDesk</h1>

  <p class="fecha"><strong>Fecha de generación:</strong> ${fecha}</p>

  <div class="cards">
    <div class="card">
      <h2>${resumen.total_tickets}</h2>
      <p>Total tickets</p>
    </div>
    <div class="card">
      <h2>${resumen.tickets_nuevos}</h2>
      <p>Nuevos</p>
    </div>
    <div class="card">
      <h2>${resumen.tickets_altos}</h2>
      <p>Prioridad Alta</p>
    </div>
    <div class="card">
      <h2>${resumen.tickets_criticos}</h2>
      <p>Críticos</p>
    </div>
  </div>

  <h2>Resumen por prioridad</h2>

  <table>
    <tr>
      <th>Crítica</th>
      <th>Alta</th>
      <th>Media</th>
      <th>Baja</th>
    </tr>
    <tr>
      <td>${resumen.tickets_criticos}</td>
      <td>${resumen.tickets_altos}</td>
      <td>${resumen.tickets_medios}</td>
      <td>${resumen.tickets_bajos}</td>
    </tr>
  </table>

  <h2>Últimos tickets registrados</h2>

  <table>
    <tr>
      <th>Código</th>
      <th>Solicitante</th>
      <th>Departamento</th>
      <th>Categoría</th>
      <th>Urgencia</th>
      <th>Prioridad</th>
      <th>Estado</th>
      <th>Técnico</th>
      <th>Fecha</th>
    </tr>
    ${filasTickets}
  </table>

  <div class="footer">
    Reporte generado automáticamente por el Sistema HelpDesk Local Automatizado con n8n.
  </div>

</body>
</html>
`;

const nombreArchivo = `reporte-helpdesk-${Date.now()}.html`;

return {
  json: {
    nombre_archivo: nombreArchivo,
    ruta_archivo: `/files/reports/${nombreArchivo}`,
    html,
    total_tickets: resumen.total_tickets,
    fecha_generacion: fecha
  }
};

const error = $json;

const workflowName =
  error.workflow?.name ||
  error.execution?.workflowName ||
  "Workflow no identificado";

const nodeName =
  error.node?.name ||
  error.execution?.lastNodeExecuted ||
  "Nodo no identificado";

const message =
  error.error?.message ||
  error.message ||
  "Error no especificado";

return {
  json: {
    workflow: workflowName,
    nodo: nodeName,
    mensaje_error: message,
    datos: JSON.stringify(error),
    fecha: new Date().toISOString()
  }
};

const body = $json;

function normalizar(texto) {
  return String(texto || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function obtenerCampo(posiblesNombres) {
  const keys = Object.keys(body);

  for (const posible of posiblesNombres) {
    const posibleNormalizado = normalizar(posible);

    for (const key of keys) {
      const keyNormalizado = normalizar(key);

      if (keyNormalizado === posibleNormalizado) {
        return body[key];
      }
    }
  }

  return "";
}

const codigo = obtenerCampo([
  "Código de ticket",
  "Codigo de ticket",
  "codigo_ticket",
  "Codigo",
  "Código"
]);

return {
  json: {
    codigo_ticket: String(codigo || "").trim().toUpperCase()
  }
};

